  1218	\begin{lemma}[Concatenation of conditionally linear functions]\label{lem:cl-concat}
  1219		\lean{MIPStarRE.QPBT.IsCondLinearOn.concat}
  1220		\leanok
  1221		\uses{def:cl-func}
  1222		Let $\ell, k \ge 0$ be integers and let $U = \F^n$, $V = \F^m$ be linear spaces. Suppose $L$ is a $k$-level CL function on $U$ and, for each $u \in L(U)$, $R_u$ is an $\ell$-level CL function on $V$. Then the \emph{concatenation} $T$ of $L$ and $\{R_u\}_u$, defined by
  1223		\[
  1224			T(x) = L(x^U) + R_{L(x^U)}(x^V)\,,
  1225		\]
  1226		is a $(k+\ell)$-level conditionally linear function on $U \oplus V$.
  1227	\end{lemma}
  1228	\begin{proof}
  1229		\leanok
  1230		\uses{def:cl-func}
  1231		By induction on $k$. The case $k = 0$ follows directly from Definition~\ref{def:cl-func}, since then $L = 0$ and $T$ acts by the single $\ell$-level function $R_0$ on the register subspace $V$. For the inductive step, write $L(x^U) = x^{L_1} + L_{>1,\,x^{L_1}}(x^{U_{>1}})$ with complementary register subspaces $U_1$ and $U_{>1}$ of $U$. For each value $x^{L_1}$, the function $T_{>1,\,x^{L_1}}$ on $U_{>1} \oplus V$ sending $x^{U_{>1} \oplus V}$ to $L_{>1,\,x^{L_1}}(x^{U_{>1}}) + R_{x^{L_1} + x^{L_{>1}}}(x^V)$ is the concatenation of the $(k-1)$-level function $L_{>1,\,x^{L_1}}$ with a family drawn from $\{R_u\}$, hence is $(k+\ell-1)$-level by the induction hypothesis. The claim then follows from Definition~\ref{def:cl-func} applied with first subspace $U_1$ and first linear map $L_1$.
  1232	\end{proof}
