  1238	\begin{lemma}[Direct sums of conditionally linear functions]\label{lem:cl-func-prod}
  1239		\lean{MIPStarRE.QPBT.IsCondLinear.directSum}
  1240		\leanok
  1241		\uses{def:cl-func, def:register-subspace}
  1242		Let $m \ge 1$ be an integer and let $V^{(1)}, V^{(2)}, \dots, V^{(m)}$ be register subspaces of $V$ such that $V = \bigoplus_{j=1}^m V^{(j)}$. Suppose that, for each $j \in \{1, 2, \dots, m\}$, $L^{(j)}$ is an $\ell_j$-level conditionally linear function on $V^{(j)}$. Then the direct sum $L = \bigoplus_{j=1}^m L^{(j)}$, defined by
  1243		\[
  1244			L(x) = \sum_{j=1}^m L^{(j)}(x^{(j)})
  1245		\]
  1246		for all $x = \sum_{j=1}^m x^{(j)} \in \bigoplus_{j=1}^m V^{(j)}$, is an $\ell$-level CL function on $V$ for $\ell = \max_j \{\ell_j\}$; the maximum exists since $m \ge 1$.
  1247		With zero-based indices, the summand labelled $r\in\{0,\ldots,m-1\}$
  1248		corresponds to the paper's summand $j=r+1$.
  1249	\end{lemma}
  1250	\begin{proof}
  1251		\leanok
  1252		\uses{def:cl-func, lem:cl-func-prod-same-level}
